import{_ as t,l,o as a,c as o,v as r,p as s,x as n,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"火线出售","description":"","frontmatter":{"title":"火线出售","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fire-sales.md","filePath":"econ/fire-sales.md","lastUpdated":1789023840000}'),E={name:"econ/fire-sales.md"};function c(m,e,B,u,A,f){const i=l("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="火线出售" tabindex="-1">火线出售 <a class="header-anchor" href="#火线出售" aria-label="Permalink to &quot;火线出售&quot;">​</a></h1><div class="epigraph"><p>当自然买家自己也缺资本时，被迫出售不再发现基本面价格，而是把流动性折扣写成系统冲击。</p><footer>—— Shleifer and Vishny, Liquidation Values and Debt Capacity, Journal of Finance, 1992；对照 Brunnermeier and Pedersen, Review of Financial Studies, 2009</footer></div><p><a href="/econ/bank-contagion">上一课</a>给出银行间网络如何把一家的清算折扣导入邻居。折扣在那里是外生的「提前卖掉拿不到持有到期值」。本课缺口是把折扣做成均衡：谁是买家、为何他们恰好也穷。Shleifer–Vishny 的火线出售，Brunnermeier 的保证金螺旋。不重画 Allen–Gale 的环形互存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Allen–Gale 已经需要一项清算折扣，否则邻居的资产不会减值。若行业内的专家才是资产的自然买家，而专家与卖方一同被同一冲击打到资本约束，则买家缺席，价格掉到局外人的估值——那是使用价值更低的人在定价。Shleifer 与 Vishny（1992）把这句话写成债务容量：清算值取决于潜在买家的财富，杠杆因此内生地脆弱。</p><p>缺口不是再指认一条银行间边，而是：即便没有直接互存，共同持有的资产在被迫出售时可以经由<strong>价格</strong>传染。Brunnermeier 与 Pedersen（2009）补上保证金：价格跌 → 保证金升 → 再卖 → 再跌。下一课存款保险删的是挤兑均衡，不自动删这条价格通道。</p><p><span class="marginnote">火线出售：被迫交易，对手方不是估值最高的使用者。折扣来自谁能买，不是来自「市场无效」的口头。基本面可以透明，价格仍可以远离持有到期值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把资产写成在专家手中产出更高。专家用债务融资。坏状态下专家净值下降，债务容量收缩，被迫把资产卖给非专家，价格等于非专家的较低估值。预期到这一点，事前杠杆已经更保守——或者在忽略外部性时仍然过高。价格渠道与债权渠道分开写：没有银行间存款，也可以有火线出售。</p>',9)),(a(),s(h,null,{default:n(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E8%B5%84%E6%9C%AC%E5%86%B2%E5%87%BB%22%5D%20--%3E%20SELL%5B%22%E8%A2%AB%E8%BF%AB%E5%87%BA%E5%94%AE%22%5D%0A%20%20SELL%20--%3E%20WHO%5B%22%E8%87%AA%E7%84%B6%E4%B9%B0%E5%AE%B6%E6%98%AF%E5%90%A6%E5%90%8C%E7%A9%B7%22%5D%0A%20%20WHO%20--%3E%20DISC%5B%22%E6%B8%85%E7%AE%97%E6%8A%98%E6%89%A3%22%5D%0A%20%20DISC%20--%3E%20MARGIN%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MARGIN%20--%3E%20SELL%0A%20%20DISC%20--%3E%20NEXT%5B%22%E9%82%BB%E5%B1%85%E5%87%80%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>不要把每一笔下跌都叫火线出售：还要有被迫与买家资本约束。共同冲击可以同时打卖家与买家，那是放大，仍要与「谣言」分开。</p><h3 id="网络边与价格边" tabindex="-1">网络边与价格边 <a class="header-anchor" href="#网络边与价格边" aria-label="Permalink to &quot;网络边与价格边&quot;">​</a></h3><p>上一课的不完全网络是债权导管。本课的价格是市场导管。两者可以叠：邻居被抽干后火灾出售，压低共同资产，第三家并未互存也被打折。系统性定义仍要求可指认的传递；价格传递的边是市场，不是电话。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是专用性加融资约束。资产的最高估值依赖专家知识或协同，专家的购买力依赖自己的净值与抵押。冲击使最高估值者缺席，价格由次优使用者决定，折扣反馈进抵押品，约束再收紧。这与柠檬不同：质量可以已知。也与 Diamond–Dybvig 的序贯服务不同：这里不必有太阳黑子排队，只要有必须满足的保证金或赎回。</p><p>宏观含义：私人清算值低于社会持有到期值，因为买家的约束不被卖方内部化。资本监管与后课的最后贷款人，针对的就是把购买力还给自然买家，而不是「禁止价格下跌」。</p><p><span class="marginnote">Brunnermeier–Pedersen：市场流动性（价差、冲击成本）与融资流动性（保证金、短期债）互相喂。本课只取螺旋，不把限价簿深度写成定理。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在此估计折扣百分比，不要把股票因子里的非流动性溢价搬进来——那是量化栏。也不要把火线出售写成做市商存货模型。下一课 <a href="/econ/deposit-insurance">存款保险</a>针对活期合同的坏均衡；未保险的批发融资与共同资产价格通道可以还在。</p><p>后课默认：清算折扣可以是均衡，来自自然买家的资本约束；价格渠道足以传染。共同冲击与火线出售仍须分开写。</p><p>限价簿上的冲击成本是协议层，见量化栏；本课停在净值与抵押。</p><p>监管若在同一时刻要求多家机构按市值补资本，会把自然买家一起变成卖方，折扣内生放大。那是约束同步，不是新的太阳黑子。私人最优杠杆仍可能高于社会，因为买方约束不被内部化。</p><p>存款保险下一课针对活期面值。批发融资、共同基金赎回，走的是本课的价格与保证金通道，保单不必自动覆盖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>火线出售：被迫卖给非自然买家，折扣由买家资本决定。</li><li>价格通道可在没有银行间债权时传染；保证金螺旋把折扣放大。</li><li>与柠檬、与太阳黑子挤兑分层：质量可透明，也不必有排队谣言。</li><li>下一课存款保险删挤兑均衡，不自动删价格与保证金通道。</li><li>冲击成本的协议层在量化栏；本课停在净值与抵押。</li><li>出处：Shleifer and Vishny, <em>JF</em> 1992；Brunnermeier and Pedersen, <em>RFS</em> 2009。</li></ul>',15))])}const D=t(E,[["render",c]]);export{S as __pageData,D as default};
